head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > toggle]<br/>DrillDown 이 적용되었을때 특정 Row 의 펼침 상태를 토글합니다.",
    "validation" : [
        "inputType='drilldown' 인 Column 이 정의되어야 동작합니다.",
        "rowIndex(필수) 파라미터로 펼침 상태를 토글하려는 Body Row 의 인덱스를 설정합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 바인딩 된 DataList 기준으로 인덱스가 설정됩니다.",
        "토글이 실행되지 않은 경우 false 를 반환합니다.",
        "정상적으로 토글이 실행된 경우에는 undefined 를 반환합니다.",
        "접혀져서 화면에 표시되지 않는 Row 는 toggle() 메소드가 실행되지 않습니다.",
        "Row 가 펼쳐질때는 직계 자식 Row 만 펼쳐지고, 접힐때는 모든 자식 Row 가 함께 접힙니다.",
        "toggle() 메소드가 정상 실행되면 onbeforetoggleclick 이벤트 없이 ontoggleclick 가 바로 발생합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - inputType="drilldown" 트리 컬럼 + depth(계층) 데이터로 3단계 DrillDown 그리드 구성
//  - drilldownRealRowIndexAll="true" : toggle(rowIndex) 의 rowIndex 를 화면 표시 인덱스가 아닌
//    바인딩 DataList 기준 인덱스로 처리 (@param 검증)
//  - 데이터(DataList idx): 영업본부(0) > 영업1팀(1) > 김영업(2), 개발본부(3) > 개발1팀(4), 관리팀(독립)(5, Leaf)
//  - showDepth="1" 로 초기에는 depth1(영업본부/개발본부/관리팀)만 표시됨
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] inputType=drilldown 트리 그리드 (drilldownRealRowIndexAll=true → toggle 의 rowIndex 는 화면 표시 인덱스가 아닌 DataList 기준). 데이터: 영업본부(0) > 영업1팀(1) > 김영업(2), 개발본부(3) > 개발1팀(4), 관리팀(독립)(5)=Leaf. 초기 showDepth=1 로 depth1(영업본부/개발본부/관리팀)만 표시.\n[절차] par_rowIndex 선택 후 toggle 버튼 클릭 -> 해당 DataList Row 의 펼침/접힘 토글.\n[확인] 반환값(성공=undefined / 미실행=false)과 현재 표시 Row 목록을 결과창에서 확인. 펼침 시 직계 자식만, 접힘 시 모든 하위 자식이 함께 접힘. 접혀서 안 보이는 Row(예: 초기 상태의 영업1팀 idx1) 토글 시 false. toggle 성공 시 onbeforetoggleclick 없이 ontoggleclick 만 출력."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). drilldown 컬럼의 depthColumn 으로 사용 (본부=1, 팀=2, 사원=3)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 : 부모 바로 아래에 그 자식이 위치(엔진 drilldown 은 순서 기반)
    //  - idx0 영업본부(depth1) > idx1 영업1팀(depth2) > idx2 김영업(depth3)
    //  - idx3 개발본부(depth1) > idx4 개발1팀(depth2)
    //  - idx5 관리팀(독립, depth1, 자식 없음) = Leaf
    let jsonData = [
        { "name": "영업본부",     "amount": 100, "depth": 1 },
        { "name": "영업1팀",      "amount": 110, "depth": 2 },
        { "name": "김영업",       "amount": 111, "depth": 3 },
        { "name": "개발본부",     "amount": 200, "depth": 1 },
        { "name": "개발1팀",      "amount": 210, "depth": 2 },
        { "name": "관리팀(독립)", "amount": 300, "depth": 1 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성 (DrillDown 트리 컬럼 + drilldownRealRowIndexAll=true)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' drilldownRealRowIndexAll="true" dataList="data:dlt_bind" rowNumVisible="true" ev:onbeforetoggleclick="scwin.target1_onbeforetoggleclick" ev:ontoggleclick="scwin.target1_ontoggleclick" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="toggle (drilldown 펼침/접힘 토글) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="360" style="" inputType="text" id="hcol1" value="조직(drilldown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="360" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// [toggle] : par_rowIndex(DataList 기준 인덱스)로 해당 Row 의 펼침/접힘 상태를 토글
//  - 반환값 : 정상 실행 → undefined / 미실행(접혀서 안 보이는 Row 등) → false
//  - 현재 화면에 표시되는 Row 목록을 함께 출력하여 펼침(직계 자식만)/접힘(하위 전체) 결과를 확인
scwin.btn_toggle_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);

    let result = target1.toggle(rowIndex);

    b.setReturnValue("toggle(" + rowIndex + ") 반환값 : " + result);

    // 현재 표시 Row 목록 (display 순회 → getRealRowIndex 로 실제 idx → DataList 에서 name 조회)
    let names = [];
    for (let i = 0; i < target1.getRowCount(); i++) {
        let real = target1.getRealRowIndex(i);
        names.push(real + ":" + dlt_bind.getCellData(real, "name"));
    }
    b.setReturnValue("현재 표시 Row(" + names.length + ") : " + names.join(", "));
};



// onbeforetoggleclick : 실제 토글 버튼 클릭 직전에만 발생. toggle() API 호출 시에는 발생하지 않음(@spec3)
scwin.target1_onbeforetoggleclick = function (rowIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onbeforetoggleclick 발생 (rowIndex : " + rowIndex + ")");
};



// ontoggleclick : 토글 상태가 모두 변경된 이후 발생. toggle() API 정상 실행 시 이 이벤트만 발생(@spec3)
//  - collapsed : true=접힘 / false=펼침 (상태 변경 이후) , rowIndex : 실제 Row 인덱스
scwin.target1_ontoggleclick = function (collapsed, rowIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ ontoggleclick 발생 (collapsed : " + collapsed + ", rowIndex : " + rowIndex + ")");
};
